(3173167, 445852, 65106, '<td valign="top">Fantastic composition ... lighting is too direct, flattens the image.</td>', 'Fantastic composition ... lighting is too direct, flattens the image.', '2007-01-03 00:25:26.000000', NULL, 1),
(3173168, 446379, 65106, '<td valign="top">Lovely ... the background is unfortunate, but the eyes are sharp and the pose is perfect.</td>', 'Lovely ... the background is unfortunate, but the eyes are sharp and the pose is perfect.', '2007-01-03 00:26:49.000000', NULL, 1),
(3173173, 446227, 65106, '<td valign="top">I like it ... would have been stronger with more depth of field. I.e. all the hair should be sharp.</td>', 'I like it ... would have been stronger with more depth of field. I.e. all the hair should be sharp.', '2007-01-03 00:28:33.000000', NULL, 1),
(3173175, 445636, 69121, '<td valign="top">Domino''s the Pizza?!?</td>', 'Domino''s the Pizza?!?', '2007-01-03 00:28:59.000000', NULL, 1),
