(3188945, 446356, 53509, '<td valign="top">The light reflection is nice.</td>', 'The light reflection is nice.', '2007-01-06 17:00:08.000000', NULL, 1),
(3188947, 445465, 53509, '<td valign="top">Good dramatic action, too bad it''s a little blurry.</td>', 'Good dramatic action, too bad it''s a little blurry.', '2007-01-06 17:00:33.000000', NULL, 1),
(3188949, 446765, 53509, '<td valign="top">What gorgeous colours and sharpness. Good work!</td>', 'What gorgeous colours and sharpness. Good work!', '2007-01-06 17:01:02.000000', NULL, 1),
(3188952, 446492, 33400, '<td valign="top">Interesting idea.  I like the way the ball is lit - like a planet lit from the sun.  Only wish the light itself were a bit softer, to minimize the one glare spot on the ball and give more definition to the left side.</td>', 'Interesting idea.  I like the way the ball is lit - like a planet lit from the sun.  Only wish the light itself were a bit softer, to minimize the one glare spot on the ball and give more definition to the left side.', '2007-01-06 17:01:24.000000', NULL, 1),
(3188953, 446762, 53509, '<td valign="top">I really like this one. It makes an ornament look much more interesting, yet still within its proper place. Bravo.</td>', 'I really like this one. It makes an ornament look much more interesting, yet still within its proper place. Bravo.', '2007-01-06 17:02:02.000000', NULL, 1),
(3188954, 446210, 53509, '<td valign="top">The orb doesn''t stand out enough from the background.</td>', 'The orb doesn''t stand out enough from the background.', '2007-01-06 17:02:21.000000', NULL, 1),
(3188955, 446650, 53509, '<td valign="top">Lovely colours, but I think a bit too much motion blur.</td>', 'Lovely colours, but I think a bit too much motion blur.', '2007-01-06 17:03:06.000000', NULL, 1),
(3188956, 446335, 53509, '<td valign="top">I wish I could see the cat''s face a little more.</td>', 'I wish I could see the cat''s face a little more.', '2007-01-06 17:03:27.000000', NULL, 1),
