(3188966, 446368, 53509, '<td valign="top">Cute gecko, too bad the photo has too many distracting elements, like the branches up top.</td>', 'Cute gecko, too bad the photo has too many distracting elements, like the branches up top.', '2007-01-06 17:04:47.000000', NULL, 1),
(3188967, 446548, 53509, '<td valign="top">Beautiful view, but it seems slightly off center</td>', 'Beautiful view, but it seems slightly off center', '2007-01-06 17:05:14.000000', NULL, 1),
(3188971, 444574, 53509, '<td valign="top">Nice colour. The focus seems a bit off.</td>', 'Nice colour. The focus seems a bit off.', '2007-01-06 17:06:12.000000', NULL, 1),
(3188972, 446699, 53509, '<td valign="top">Terribly blurry and hard to look at.</td>', 'Terribly blurry and hard to look at.', '2007-01-06 17:06:27.000000', NULL, 1),
(3188974, 446202, 53509, '<td valign="top">I can barely see it.</td>', 'I can barely see it.', '2007-01-06 17:06:54.000000', NULL, 1),
