(3193261, 445346, 18799, '<td valign="top">I will (as others I''m sure) will be interested to see how this was done.  9</td>', 'I will (as others I''m sure) will be interested to see how this was done.  9', '2007-01-07 22:40:19.000000', NULL, 1),
(3193264, 446442, 61012, '<td valign="top">Very nice exposure!</td>', 'Very nice exposure!', '2007-01-07 22:40:59.000000', NULL, 1),
