(3199887, 446277, 71402, '<td valign="top">Greeting card worthy.  Definately.</td>', 'Greeting card worthy.  Definately.', '2007-01-09 11:36:02.000000', NULL, 1),
(3199890, 446540, 71402, '<td valign="top">Excellent contrast, I LOVE the lines.</td>', 'Excellent contrast, I LOVE the lines.', '2007-01-09 11:36:28.000000', NULL, 1),
