(3201684, 445707, 35602, '<td valign="top">Could be a neat image in black light poster.</td>', 'Could be a neat image in black light poster.', '2007-01-09 19:51:54.000000', NULL, 1),
(3201718, 446756, 35602, '<td valign="top">Awesome composition.  Love the roofline and how it frames the boy.  Really great job.</td>', 'Awesome composition.  Love the roofline and how it frames the boy.  Really great job.', '2007-01-09 20:00:48.000000', NULL, 1),
(3201721, 445112, 66668, '<td valign="top">I hope this was a quick shoot, brrrrrrrrrr</td>', 'I hope this was a quick shoot, brrrrrrrrrr', '2007-01-09 20:01:27.000000', NULL, 1),
